<?php

namespace App\Services;

class PaklaringTemplate
{
    /**
     * Mengambil URL template blangko sertifikat paklaring.
     * Jika file fisik belum ada di server (misal di cPanel / shared hosting),
     * method ini otomatis memulihkan file tersebut ke public/images/paklaring/
     * atau mengembalikan data URI base64 jika direktori tidak dapat ditulis.
     */
    public static function getTemplateUrl(): string
    {
        $path = public_path('images/paklaring/exact_base_template.png');

        if (!file_exists($path)) {
            try {
                $dir = dirname($path);
                if (!is_dir($dir)) {
                    @mkdir($dir, 0755, true);
                }
                @file_put_contents($path, base64_decode(self::BASE64_DATA));
            } catch (\Throwable $e) {
                // Abaikan jika folder read-only
            }
        }

        if (file_exists($path)) {
            return asset('images/paklaring/exact_base_template.png') . '?v=' . filemtime($path);
        }

        return self::getDataUri();
    }

    public static function getDataUri(): string
    {
        return 'data:image/png;base64,' . self::BASE64_DATA;
    }

    public const BASE64_DATA = '';
}
